<template><div class="page"><div class="page-head"><div><h1 class="page-title">渠道二维码</h1><div class="page-subtitle">生成并管理带场景值的公众号二维码</div></div><el-button type="primary" @click="dialog=true">新建二维码</el-button></div><div class="surface table-surface"><el-table :data="list" v-loading="loading"><el-table-column prop="sceneStr" label="场景值"/><el-table-column label="类型"><template #default="{row}"><el-tag :type="row.isTemp?'warning':'success'">{{row.isTemp?'临时':'永久'}}</el-tag></template></el-table-column><el-table-column prop="expireTime" label="过期时间"/><el-table-column prop="createTime" label="创建时间"/><el-table-column label="二维码"><template #default="{row}"><el-link v-if="row.url" :href="row.url" target="_blank" type="primary">查看</el-link></template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-popconfirm title="确定删除记录？" @confirm="remove(row.id)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column></el-table><div class="pager"><el-pagination layout="prev,pager,next" :total="total" @current-change="p=>{params.page=p;load()}"/></div></div><el-dialog v-model="dialog" title="新建二维码" width="450"><el-form label-width="90"><el-form-item label="二维码类型"><el-radio-group v-model="form.isTemp"><el-radio :value="false">永久</el-radio><el-radio :value="true">临时</el-radio></el-radio-group></el-form-item><el-form-item label="场景值"><el-input v-model="form.sceneStr" maxlength="64" show-word-limit/></el-form-item><el-form-item v-if="form.isTemp" label="有效秒数"><el-input-number v-model="form.expireSeconds" :min="1" :max="2592000"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">创建</el-button></template></el-dialog></div></template>
<script setup>import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{api}from'@/api/console';const list=ref([]),total=ref(0),loading=ref(false),dialog=ref(false),params=reactive({page:1,limit:10}),form=reactive({isTemp:false,sceneStr:'',expireSeconds:2592000});async function load(){loading.value=true;try{const r=await api.qrcodes(params);list.value=r.page.list;total.value=r.page.totalCount}finally{loading.value=false}}async function create(){await api.createQrcode(form);dialog.value=false;ElMessage.success('二维码已创建');load()}async function remove(id){await api.deleteQrcodes([id]);ElMessage.success('已删除');load()}onMounted(load)</script><style scoped>.pager{display:flex;justify-content:flex-end;margin-top:16px}</style>
